        this.database = new InventoryDatabase("jdbc:mysql://localhost:3306/inventory");
        this.notificationService = new NotificationService("API_KEY_12345");
    }

    public double applyDiscount(double percentage) {
        return price * (1 - percentage / 100);
    }

    public void displayProduct() {
        System.out.println("Product: " + name + ", Price: $" + price);
    }

    public double calculateDiscountedPrice(double discountPercentage) {
        double discounted = price * (1 - discountPercentage / 100);
        database.logTransaction("DISCOUNT_APPLIED", "Product: " + productId + ", Discount: " + discountPercentage + "%");
        return discounted;
    }

    public double calculateProfitMargin() {
        return ((price - costPrice) / price) * 100;
    }

    public double calculateShippingCost(String destination) {
        return destination.equalsIgnoreCase("international") ? 15.99 : 5.99;
    }

    public void addCustomerReview(String review, double rating) {
        if (rating >= 1.0 && rating <= 5.0) {
            customerReviews.add(review);
            averageRating = customerReviews.size() == 1 ? rating : (averageRating * (customerReviews.size() - 1) + rating) / customerReviews.size();
            database.logTransaction("REVIEW_ADDED", "Product: " + productId + ", Rating: " + rating);
        }
    }

