        emailService.sendEmail(email, "Annual Performance Review - " + name, reviewEmail);

        complianceLogger.logEvent("PERFORMANCE_REVIEW", "Annual review completed for employee: " + employeeId);
    }

    public String generatePerformanceReviewReport() {
        StringBuilder report = new StringBuilder();
        report.append("=== ANNUAL PERFORMANCE REVIEW ===\n");
        report.append("Employee: ").append(name).append(" (").append(employeeId).append(")\n");
        report.append("Department: ").append(department).append("\n");
