            emailService.sendEmail("hr@company.com", "Significant Rating Change - " + name, alertEmail);
        }

        logPerformanceChange(oldRating, newRating);
    }

    public String createRatingChangeAlert(double oldRating, double newRating) {
        return "PERFORMANCE ALERT:\n\nEmployee: " + name + " (" + employeeId + ")\nOld Rating: " + oldRating + "\nNew Rating: " + newRating + "\nChange: " + (newRating > oldRating ? "IMPROVEMENT" : "DECLINE");
