    }

    public void processCustomerReview(Book book, String customerEmail, String review, double rating) {
        ValidationService validator = new ValidationService();
        if (validator.validateRating(rating)) {
            book.getReviews().add(review);
            book.getCustomerEmails().add(customerEmail);
            book.setAverageRating(recalculateRatingMetrics(book.getAverageRating(), book.getReviews().size(), rating));
            sendReviewConfirmationEmail(book, customerEmail);
            logReviewActivity(book.getIsbn(), customerEmail, rating);
        }
