    private double recalculateRatingMetrics(double currentAverage, int reviewCount, double newRating) {
        return reviewCount == 1 ? newRating : (currentAverage * (reviewCount - 1) + newRating) / reviewCount;
    }

    private void sendReviewConfirmationEmail(Book book, String customerEmail) {
