        this.emailContentService = new EmailContentService();
        this.inventoryService = new InventoryManagementService();
    }

    public void processSaleTransaction(Book book, String customerEmail) {
        book.setTotalSales(book.getTotalSales() + 1);
        book.getCustomerEmails().add(customerEmail);

        inventoryService.updateInventoryStatus(book);

        dbService.updateSalesData(book.getIsbn(), book.getTotalSales());

        String receiptEmail = emailContentService.generateSalesReceiptEmail(book);
        emailService.sendEmail(customerEmail, "Purchase Confirmation - " + book.getTitle(), receiptEmail);

        logSalesTransaction(book, customerEmail);

        if (book.getTotalSales() % 100 == 0) {
            sendMilestoneNotification(book);
        }
    }

    private void logSalesTransaction(Book book, String customerEmail) {
        PricingService pricingService = new PricingService();
        double finalPrice = pricingService.calculateFinalPrice(book.getPrice(), book.getDiscountRate());
        String logDetails = "Sale completed - Book: " + book.getIsbn() + ", Customer: " + customerEmail + ", Price: $" + finalPrice;
        dbService.logTransaction("SALE_COMPLETED", logDetails);
    }

    private void sendMilestoneNotification(Book book) {
        String subject = "Sales Milestone Reached: " + book.getTitle();
        String body = "Congratulations! '" + book.getTitle() + "' has reached " + book.getTotalSales() + " sales!";
        emailService.sendEmail("sales@bookstore.com", subject, body);
    }
}

