    private AnalyticsService analytics;
    private InventoryDatabase database;
    private EmailContentService emailContentService;
    private ValidationService validator;

    public ReviewManagementService() {
        this.emailService = new EmailService("smtp.ecommerce.com");
        this.analytics = new AnalyticsService("analytics_key_456");
        this.database = new InventoryDatabase("jdbc:mysql://localhost:3306/inventory");
        this.emailContentService = new EmailContentService();
        this.validator = new ValidationService();
    }

    public void processAdvancedReview(Product product, String customerEmail, String review, double rating, String region) {
        if (validator.validateReview(rating, review)) {
            product.getCustomerReviews().add(review);
            product.getCustomerEmails().add(customerEmail);
            product.setAverageRating(recalculateAdvancedRating(product.getAverageRating(), product.getCustomerReviews().size(), rating));

            String thankYouEmail = emailContentService.createReviewThankYouEmail(product.getName(), customerEmail, rating);
            emailService.sendEmail(customerEmail, "Thank you for your review!", thankYouEmail);

            java.util.Map<String, String> analyticsData = new java.util.HashMap<>();
            analyticsData.put("rating", String.valueOf(rating));
            analyticsData.put("region", region);
            analytics.trackEvent("REVIEW_ADDED", product.getProductId(), analyticsData);

            database.logTransaction("REVIEW_PROCESSED", "Product: " + product.getProductId() + ", Rating: " + rating + ", Region: " + region);

            if (product.getAverageRating() >= 4.5 && product.getCustomerReviews().size() >= 10) {
                triggerBestSellerPromotion(product);
            }
        }
    }

    private double recalculateAdvancedRating(double currentAverage, int reviewCount, double newRating) {
        return reviewCount == 1 ? newRating : (currentAverage * (reviewCount - 1) + newRating) / reviewCount;
    }

    private void triggerBestSellerPromotion(Product product) {
        String promoEmail = "BESTSELLER ALERT: " + product.getName() + " is now a top-rated product with " + product.getAverageRating() + " stars!";
        emailService.sendBulkEmail(product.getCustomerEmails(), "Special Offer on Bestseller", promoEmail);
        analytics.trackEvent("BESTSELLER_PROMOTION", product.getProductId(), new java.util.HashMap<>());
    }
}

class SalesProcessingService {
    private PaymentProcessor paymentProcessor;
    private ShippingService shippingService;
    private InventoryDatabase database;
    private EmailService emailService;
    private AnalyticsService analytics;
    private PricingCalculationService pricingService;
    private EmailContentService emailContentService;
    private StockAlertService stockAlertService;

    public SalesProcessingService() {
        this.paymentProcessor = new PaymentProcessor("pay_api_key_123");
        this.shippingService = new ShippingService("FedEx");
        this.database = new InventoryDatabase("jdbc:mysql://localhost:3306/inventory");
        this.emailService = new EmailService("smtp.ecommerce.com");
        this.analytics = new AnalyticsService("analytics_key_456");
        this.pricingService = new PricingCalculationService();
        this.emailContentService = new EmailContentService();
        this.stockAlertService = new StockAlertService();
    }

    public String processComplexSale(Product product, int quantity, String customerEmail, String shippingAddress, String region, String cardNumber) {
        if (product.getStockQuantity() < quantity) {
            return "FAILED: Insufficient stock";
        }

        double unitPrice = pricingService.calculateDynamicPricing(product.getPrice(), product.getTotalSales(), product.getStockQuantity(), product.getDiscountRate());
        double discount = pricingService.calculateTieredDiscount(quantity);
        double subtotal = unitPrice * quantity * (1 - discount);
        double shippingCost = shippingService.calculateShippingRate(region, product.getWeight() * quantity);
        double totalAmount = subtotal + shippingCost;

        if (!paymentProcessor.processPayment(totalAmount, cardNumber)) {
            return "FAILED: Payment declined";
        }

        product.setStockQuantity(product.getStockQuantity() - quantity);
        product.setTotalSales(product.getTotalSales() + quantity);
        product.getSalesByRegion().put(region, product.getSalesByRegion().getOrDefault(region, 0) + quantity);

        String trackingNumber = shippingService.createShipment(shippingAddress, product.getWeight() * quantity);

        database.updateStock(product.getProductId(), product.getStockQuantity());

        String receiptEmail = emailContentService.generateAdvancedReceipt(product.getName(), product.getProductId(), quantity, unitPrice, discount, shippingCost, totalAmount, trackingNumber);
        emailService.sendEmail(customerEmail, "Order Confirmation - " + product.getName(), receiptEmail);

        stockAlertService.checkAdvancedStockAlerts(product, emailService, analytics);

        java.util.Map<String, String> saleData = new java.util.HashMap<>();
        saleData.put("quantity", String.valueOf(quantity));
        saleData.put("amount", String.valueOf(totalAmount));
        saleData.put("region", region);
        analytics.trackEvent("SALE_COMPLETED", product.getProductId(), saleData);

        database.logTransaction("COMPLEX_SALE", "Product: " + product.getProductId() + ", Qty: " + quantity + ", Amount: $" + totalAmount + ", Region: " + region);

        return "SUCCESS: Order placed - Tracking: " + trackingNumber;
    }
}

