        if (product.getStockQuantity() <= 5) {
            String urgentAlert = "URGENT: Product " + product.getName() + " (" + product.getProductId() + ") critically low - Only " + product.getStockQuantity() + " units left!";
            emailService.sendEmail("urgent@company.com", "Critical Stock Alert", urgentAlert);
            analytics.trackEvent("CRITICAL_STOCK_ALERT", product.getProductId(), new java.util.HashMap<>());
