}

class InventoryManagementService {
    private InventoryDatabase database;
    private EmailService emailService;
    private AnalyticsService analytics;
    private EmailContentService emailContentService;

    public InventoryManagementService() {
        this.database = new InventoryDatabase("jdbc:mysql://localhost:3306/inventory");
        this.emailService = new EmailService("smtp.ecommerce.com");
        this.analytics = new AnalyticsService("analytics_key_456");
        this.emailContentService = new EmailContentService();
    }

    public void executeSmartRestock(Product product, String supplierEmail) {
        int recommendedStock = calculateOptimalStockLevel(product.getTotalSales());
        int restockQuantity = recommendedStock - product.getStockQuantity();

        if (restockQuantity > 0) {
            product.setStockQuantity(product.getStockQuantity() + restockQuantity);
            database.updateStock(product.getProductId(), product.getStockQuantity());

            String restockEmail = emailContentService.generateSmartRestockEmail(product.getName(), product.getProductId(), restockQuantity, product.getStockQuantity(), recommendedStock, product.getTotalSales());
            emailService.sendEmail(supplierEmail, "Smart Restock Completed - " + product.getName(), restockEmail);

            analytics.trackEvent("SMART_RESTOCK", product.getProductId(), java.util.Map.of("quantity", String.valueOf(restockQuantity)));
            database.logTransaction("SMART_RESTOCK", "Product: " + product.getProductId() + ", Added: " + restockQuantity + ", Target: " + recommendedStock);
        }
    }

    private int calculateOptimalStockLevel(int totalSales) {
        int averageMonthlySales = totalSales / Math.max(1, java.time.LocalDate.now().getMonthValue());
        int seasonalFactor = java.time.LocalDate.now().getMonthValue() == 12 ? 2 : 1;
        return averageMonthlySales * 2 * seasonalFactor;
    }
}

