class SalaryCalculationService:
    def calculate_base_salary(self, base_salary: float, years_of_service: int) -> float:
        return base_salary + (years_of_service * 1000)

    def calculate_performance_bonus(self, base_salary: float, performance_rating: float, years_of_service: int) -> float:
        base_bonus = base_salary * 0.12
        rating_multiplier = performance_rating / 5.0
        service_multiplier = min(years_of_service * 0.02, 0.15)
        return base_bonus * rating_multiplier * (1.0 + service_multiplier)

    def calculate_overtime_compensation(self, base_salary: float, overtime_hours: float) -> float:
        if overtime_hours > 0:
            hourly_rate = base_salary / (52 * 40)
            return overtime_hours * hourly_rate * 1.5
        return 0.0

    def calculate_total_compensation(self, base_salary: float, years_of_service: int, performance_rating: float, overtime_hours: float) -> float:
        salary = self.calculate_base_salary(base_salary, years_of_service)
        bonus = self.calculate_performance_bonus(base_salary, performance_rating, years_of_service)
        overtime = self.calculate_overtime_compensation(base_salary, overtime_hours)
        return salary + bonus + overtime

class TaxCalculationService:
    def calculate_federal_tax(self, gross_pay: float) -> float:
        if gross_pay <= 4000:
            return gross_pay * 0.18
        elif gross_pay <= 8000:
            return gross_pay * 0.22
        else:
            return gross_pay * 0.28

    def calculate_state_tax(self, gross_pay: float) -> float:
        return gross_pay * 0.085

    def calculate_social_security_tax(self, gross_pay: float) -> float:
        return min(gross_pay * 0.062, 8853.60)

    def calculate_total_tax(self, gross_pay: float) -> float:
        return (self.calculate_federal_tax(gross_pay) + 
                self.calculate_state_tax(gross_pay) + 
                self.calculate_social_security_tax(gross_pay))

