    def generate_compensation_breakdown(self, employee, salary_service, tax_service) -> str:
        salary = salary_service.calculate_base_salary(employee.get_base_salary(), employee.get_years_of_service())
        bonus = salary_service.calculate_performance_bonus(employee.get_base_salary(), employee.get_performance_rating(), employee.get_years_of_service())
        overtime = salary_service.calculate_overtime_compensation(employee.get_base_salary(), employee.get_overtime_hours())
        gross = salary + bonus + overtime
        federal_tax = tax_service.calculate_federal_tax(gross)
        state_tax = tax_service.calculate_state_tax(gross)
        ss_tax = tax_service.calculate_social_security_tax(gross)
        total_tax = federal_tax + state_tax + ss_tax
        net_pay = gross - total_tax

        breakdown = []
        breakdown.append("=== COMPENSATION BREAKDOWN ===")
        breakdown.append(f"Base Salary: ${salary:.2f}")
        breakdown.append(f"Performance Bonus: ${bonus:.2f}")
        breakdown.append(f"Overtime Pay: ${overtime:.2f}")
        breakdown.append(f"Gross Pay: ${gross:.2f}")
        breakdown.append(f"Federal Tax: ${federal_tax:.2f}")
        breakdown.append(f"State Tax: ${state_tax:.2f}")
        breakdown.append(f"Social Security: ${ss_tax:.2f}")
        breakdown.append(f"Net Pay: ${net_pay:.2f}")
