class Book:
    def __init__(self, title: str, author: str, content: str):
        self.title = title
        self.author = author
        self.content = content
        self.publish_date = datetime.now()
        self.reviews = []
        self.customer_emails = []
        self.average_rating = 0.0
        self.total_sales = 0
        self.is_available = True
        self.format = "paperback"
        self.discount_rate = 0.0

        self.file_storage = FileStorage("/books/storage")
        self.email_service = EmailService("smtp.bookstore.com")
        self.db_service = DatabaseService("jdbc:mysql://localhost:3306/bookstore")
        self.printer = PrinterService("BookStore_Printer_001")

        self.initialize_book_defaults()

    def print_book(self):
        print(f"Title: {self.title}\nAuthor: {self.author}\nContent: {self.content}")

    def save_to_file(self, filename: str):
        book_data = self.format_complete_book_data()
        self.file_storage.save_to_file(filename, book_data)
        self.db_service.save_book(self)

    def format_complete_book_data(self) -> str:
        return f"TITLE: {self.title}\nAUTHOR: {self.author}\nISBN: {self.isbn}\nGENRE: {self.genre}\nPAGES: {self.page_count}\nPRICE: ${self.calculate_final_price()}\nFORMAT: {self.format}\nPUBLISHER: {self.publisher}\nRATING: {self.average_rating}\nSALES: {self.total_sales}\nAVAILABLE: {self.is_available}\nCONTENT: {self.content}"

    def generate_unique_isbn(self):
        timestamp = int(datetime.now().timestamp() * 1000)
        category = "FIC" if self.genre and self.genre == "fiction" else "NF"
        self.isbn = f"978-{category}-{timestamp % 100000}-{random.randint(0, 99):02d}"

    def calculate_dynamic_page_count(self):
        if self.content:
            base_pages = len(self.content) // 250
            format_multiplier = 1.2 if self.format == "hardcover" else 1.0
            self.page_count = max(1, int(base_pages * format_multiplier))

    def validate_complete_book_data(self) -> bool:
        return (self.title and self.title.strip() and 
                self.author and self.author.strip() and 
                self.validate_isbn_format(self.isbn) and 
                self.validate_price_range(self.price) and 
                self.content and len(self.content) > 0)

    def validate_isbn_format(self, isbn: str) -> bool:
        if not isbn:
            return False
        clean = ''.join(c for c in isbn if c.isdigit() or c == 'X')
        return len(clean) == 10 or len(clean) == 13

    def validate_price_range(self, price: float) -> bool:
        return 0.99 <= price <= 999.99

    def process_customer_review(self, customer_email: str, review: str, rating: float):
        if 1.0 <= rating <= 5.0:
            self.reviews.append(review)
            self.customer_emails.append(customer_email)
            self.recalculate_rating_metrics(rating)
            self.send_review_confirmation_email(customer_email)
            self.log_review_activity(customer_email, rating)

    def recalculate_rating_metrics(self, new_rating: float):
        if len(self.reviews) == 1:
            self.average_rating = new_rating
        else:
            self.average_rating = (self.average_rating * (len(self.reviews) - 1) + new_rating) / len(self.reviews)

    def send_review_confirmation_email(self, customer_email: str):
        subject = f"Thank you for reviewing: {self.title}"
        body = self.create_review_thank_you_email()
        self.email_service.send_email(customer_email, subject, body)

    def create_review_thank_you_email(self) -> str:
        return f"Dear Reader,\n\nThank you for reviewing '{self.title}' by {self.author}.\nYour feedback helps other readers discover great books!\n\nBest regards,\nBookstore Team"

    def log_review_activity(self, customer_email: str, rating: float):
        log_details = f"Review added - Book: {self.isbn}, Customer: {customer_email}, Rating: {rating}"
        self.db_service.log_transaction("REVIEW_ADDED", log_details)

    def process_sale_transaction(self, customer_email: str):
        self.total_sales += 1
        self.customer_emails.append(customer_email)

        self.update_inventory_status()

        self.db_service.update_sales_data(self.isbn, self.total_sales)

        receipt_email = self.generate_sales_receipt_email()
        self.email_service.send_email(customer_email, f"Purchase Confirmation - {self.title}", receipt_email)

        self.log_sales_transaction(customer_email)

        if self.total_sales % 100 == 0:
            self.send_milestone_notification()

    def update_inventory_status(self):
        if self.total_sales > 1000:
            self.is_available = random.random() > 0.1

    def generate_sales_receipt_email(self) -> str:
        final_price = self.calculate_final_price()
        return f"PURCHASE RECEIPT\n\nTitle: {self.title}\nAuthor: {self.author}\nISBN: {self.isbn}\nFormat: {self.format}\nOriginal Price: ${self.price}\nDiscount: {self.discount_rate * 100}%\nFinal Price: ${final_price:.2f}\nThank you for your purchase!"

    def log_sales_transaction(self, customer_email: str):
        log_details = f"Sale completed - Book: {self.isbn}, Customer: {customer_email}, Price: ${self.calculate_final_price()}"
        self.db_service.log_transaction("SALE_COMPLETED", log_details)

    def send_milestone_notification(self):
