class PageCalculationService:
    def calculate_dynamic_page_count(self, content: str, format_type: str) -> int:
        if content:
            base_pages = len(content) // 250
            format_multiplier = 1.2 if format_type and format_type == "hardcover" else 1.0
            return max(1, int(base_pages * format_multiplier))
        return 1

class ValidationService:
    def validate_complete_book_data(self, title: str, author: str, isbn: str, price: float, content: str) -> bool:
        return (title and title.strip() and 
                author and author.strip() and 
                self.validate_isbn_format(isbn) and 
                self.validate_price_range(price) and 
                content and len(content) > 0)

    def validate_isbn_format(self, isbn: str) -> bool:
        if not isbn:
            return False
        clean = ''.join(c for c in isbn if c.isdigit() or c == 'X')
        return len(clean) == 10 or len(clean) == 13

    def validate_price_range(self, price: float) -> bool:
        return 0.99 <= price <= 999.99

    def validate_rating(self, rating: float) -> bool:
