        if len(self.customer_reviews) == 1:
            self.average_rating = new_rating
        else:
            weighted_total = self.average_rating * (len(self.customer_reviews) - 1) + new_rating
            self.average_rating = weighted_total / len(self.customer_reviews)

        if self.average_rating >= 4.5 and len(self.customer_reviews) >= 10:
            self.trigger_best_seller_promotion()

