            return "FAILED: Insufficient stock"

        unit_price = self.calculate_dynamic_pricing()
        discount = self.calculate_tiered_discount(quantity)
        subtotal = unit_price * quantity * (1 - discount)
        shipping_cost = self.shipping_service.calculate_shipping_rate(region, self.weight * quantity)
        total_amount = subtotal + shipping_cost

        if not self.payment_processor.process_payment(total_amount, card_number):
            return "FAILED: Payment declined"

        self.stock_quantity -= quantity
        self.total_sales += quantity
        self.sales_by_region[region] = self.sales_by_region.get(region, 0) + quantity

        tracking_number = self.shipping_service.create_shipment(shipping_address, self.weight * quantity)

