class PricingCalculationService:
    def __init__(self):
        self.shipping_service = ShippingService("FedEx")

    def apply_discount(self, price, percentage):
        return price * (1 - percentage / 100)

    def calculate_dynamic_pricing(self, base_price, total_sales, stock_quantity, discount_rate):
        demand_multiplier = 1.2 if total_sales > 1000 else (1.1 if total_sales > 500 else 1.0)
        stock_multiplier = 1.15 if stock_quantity < 10 else 1.0
        import datetime
        seasonal_multiplier = 1.25 if datetime.datetime.now().month == 12 else 1.0
        return base_price * demand_multiplier * stock_multiplier * seasonal_multiplier * (1 - discount_rate)

    def calculate_complex_profit_margin(self, base_price, total_sales, stock_quantity, discount_rate, cost_price, weight):
        selling_price = self.calculate_dynamic_pricing(base_price, total_sales, stock_quantity, discount_rate)
        shipping_cost = self.shipping_service.calculate_shipping_rate("domestic", weight)
        total_cost = cost_price + shipping_cost + (selling_price * 0.03)
        return ((selling_price - total_cost) / selling_price) * 100

    def calculate_tiered_discount(self, quantity):
        if quantity >= 100:
            return 0.20
        elif quantity >= 50:
            return 0.15
        elif quantity >= 10:
            return 0.10
        elif quantity >= 5:
            return 0.05
        return 0.0


