class ProductIdGenerationService {
    fun generateProductId(): String {
        return "PRD-${System.currentTimeMillis() % 100000}"
    }
}

class PricingCalculationService {
    fun applyDiscount(price: Double, percentage: Double): Double {
        return price * (1 - percentage / 100)
    }

    fun calculateDiscountedPrice(price: Double, discountPercentage: Double): Double {
        return price * (1 - discountPercentage / 100)
    }

    fun calculateProfitMargin(price: Double, costPrice: Double): Double {
        return ((price - costPrice) / price) * 100
    }

    fun calculateShippingCost(destination: String): Double {
        return if (destination.lowercase() == "international") 15.99 else 5.99
    }
}

class ReviewManagementService {
    private val database = InventoryDatabase("jdbc:mysql://localhost:3306/inventory")

    fun addCustomerReview(product: Product, review: String, rating: Double) {
        if (rating in 1.0..5.0) {
            product.getCustomerReviews().add(review)
            product.setAverageRating(calculateNewAverageRating(product.getAverageRating(), product.getCustomerReviews().size, rating))
            database.logTransaction("REVIEW_ADDED", "Product: ${product.getProductId()}, Rating: $rating")
        }
    }

    private fun calculateNewAverageRating(currentAverage: Double, reviewCount: Int, newRating: Double): Double {
        return if (reviewCount == 1) newRating else (currentAverage * (reviewCount - 1) + newRating) / reviewCount
    }
}

class SalesProcessingService {
    private val database = InventoryDatabase("jdbc:mysql://localhost:3306/inventory")
    private val notificationService = NotificationService("API_KEY_12345")
    private val stockAlertService = StockAlertService()

    fun processSale(product: Product, quantity: Int, customerEmail: String) {
        if (product.getStockQuantity() >= quantity) {
            product.setStockQuantity(product.getStockQuantity() - quantity)
            product.setTotalSales(product.getTotalSales() + quantity)

            database.updateStock(product.getProductId(), product.getStockQuantity())
            notificationService.sendEmail(customerEmail, "Purchase Confirmation", "Receipt for ${product.getName()}")

            stockAlertService.checkLowStockAlert(product, notificationService)

            database.logTransaction("SALE_COMPLETED", "Product: ${product.getProductId()}, Quantity: $quantity")
        }
    }
}

class StockAlertService {
    fun checkLowStockAlert(product: Product, notificationService: NotificationService) {
        if (product.getStockQuantity() <= 10) {
            notificationService.sendEmail("inventory@company.com", "Low Stock Alert", "Product ${product.getName()} low stock")
        }
    }
}

class InventoryManagementService {
    private val database = InventoryDatabase("jdbc:mysql://localhost:3306/inventory")
    private val notificationService = NotificationService("API_KEY_12345")

    fun restockProduct(product: Product, quantity: Int, supplierEmail: String) {
        product.setStockQuantity(product.getStockQuantity() + quantity)
        database.updateStock(product.getProductId(), product.getStockQuantity())
        notificationService.sendEmail(supplierEmail, "Restock Confirmation", "Added $quantity units")
        database.logTransaction("RESTOCK_COMPLETED", "Product: ${product.getProductId()}, Added: $quantity")
    }
}

class ReportGenerationService {
    fun generateProductReport(product: Product): String {
        return "Product: ${product.getName()}\nID: ${product.getProductId()}\nPrice: $${product.getPrice()}\nStock: ${product.getStockQuantity()}\nSales: ${product.getTotalSales()}\nRating: ${product.getAverageRating()}"
    }
}

class ProductDisplayService {
    fun displayProduct(product: Product) {
        println("Product: ${product.getName()}, Price: $${product.getPrice()}")
    }

    fun displayDetailedProduct(product: Product) {
        println("${product.getName()} (${product.getProductId()}) - $${product.getPrice()} - Stock: ${product.getStockQuantity()} - Rating: ${product.getAverageRating()}")
    }
}

class DiscountService {
    private val database = InventoryDatabase("jdbc:mysql://localhost:3306/inventory")
    private val pricingService = PricingCalculationService()

    fun calculateDiscountedPrice(product: Product, discountPercentage: Double): Double {
        val discounted = pricingService.calculateDiscountedPrice(product.getPrice(), discountPercentage)
        database.logTransaction("DISCOUNT_APPLIED", "Product: ${product.getProductId()}, Discount: $discountPercentage%")
        return discounted
    }
}

class Product(private var name: String, private var price: Double) {
    private val productId: String
    private var stockQuantity: Int = 100
    private val customerReviews: MutableList<String> = mutableListOf()
    private var averageRating: Double = 0.0
    private var totalSales: Int = 0
    private val costPrice: Double = price * 0.6

    init {
        initializeProduct()
    }

    private fun initializeProduct() {
        val idService = ProductIdGenerationService()
